def una_per_reparto(apps, schema_editor):
    """What there is becomes the open Alta Squadriglia of each reparto, two linked ones sharing
    one, named «Alta Squadriglia» for the staff to rename, with its periods and antechamber
    (DEC-440). A reparto no longer active gets one only with periods, closed."""
    Unita = apps.get_model("organizzazione", "Unita")
    Membro = apps.get_model("eventi", "MembroAltaSquadriglia")
    Alta = apps.get_model("eventi", "AltaSquadriglia")
    oggi = date.today()
    fatti: set[int] = set()
    for reparto in Unita.objects.filter(tipo="REPARTO").order_by("pk"):
        if reparto.pk in fatti:
            continue
        reparti = [reparto.pk]
        collegata = Unita.objects.filter(pk=reparto.collegata_a_id, tipo="REPARTO").first()
        if collegata is not None:
            reparti.append(collegata.pk)
        fatti.update(reparti)
        membri = Membro.objects.filter(reparto_id__in=reparti)
        attivo = reparto.attiva or (collegata is not None and collegata.attiva)
        if not attivo and not membri.exists():
            continue
        primo = membri.exclude(data_inizio=None).order_by("data_inizio").first()
        alta = Alta.objects.create(
            reparto=reparto,
            nome="Alta Squadriglia",
            aperta_il=primo.data_inizio if primo else oggi,
            chiusa_il=None if attivo else oggi,
        )
        membri.update(alta=alta)


